const fs   = require('fs');
const path = require('path');
const base = '/Users/jneal/n8n_projects';

const dirs = fs.readdirSync(base).filter(d => {
  try {
    const full = path.join(base, d);
    if (!fs.statSync(full).isDirectory()) return false;
    // Phase 2 must have produced media_timeline.json
    const hasTimeline = fs.existsSync(path.join(full, 'scripts', 'media_timeline.json'));
    // Skip if Phase 3 already complete
    const alreadyDone = fs.existsSync(path.join(full, 'renders', 'render_complete.json'));
    return hasTimeline && !alreadyDone;
  } catch(e) { return false; }
}).sort();

if (dirs.length === 0)
  throw new Error('No Phase 3 ready projects. Run Phase 2 first to produce scripts/media_timeline.json.');

const rows = dirs.map((d, i) => ({
  caseNumber: i + 1,
  slug:       d,
  projectDir: path.join(base, d)
}));

return [{ json: { readyProjects: dirs, allRows: JSON.stringify(rows) } }];

const fs   = require('fs');
const path = require('path');
const selection = parseInt($json['CASE NUMBER'], 10);
const allRows   = JSON.parse($('Scan Projects').first().json.allRows);

if (!selection || selection < 1 || selection > allRows.length)
  throw new Error(`Invalid selection: ${selection}. Choose 1–${allRows.length}.`);

const row        = allRows[selection - 1];
const projectDir = row.projectDir;
const slug       = row.slug;

const timelinePath = path.join(projectDir, 'scripts', 'media_timeline.json');
const timeline     = JSON.parse(fs.readFileSync(timelinePath, 'utf-8'));
const topic        = timeline.topic || slug;

const renderDir = path.join(projectDir, 'renders');

// Write execution -> projectDir mapping for error trigger
const execMapDir = '/Users/jneal/n8n_projects/.exec_map';
fs.mkdirSync(execMapDir, { recursive: true });
fs.writeFileSync(path.join(execMapDir, $execution.id), projectDir, 'utf-8');

return [{ json: {
  slug,
  projectDir,
  topic,
  timelinePath,
  renderDir,
  renderScript:       '/Users/jneal/n8n_projects/render.js',
  renderLogPath:      path.join(renderDir, 'render.log'),
  renderPidPath:      path.join(renderDir, 'render.pid'),
  renderCompletePath: path.join(renderDir, 'render_complete.json'),
  finalVideoPath:     path.join(renderDir, 'final_video.mp4'),
  thumbnailPath:      path.join(renderDir, 'thumbnail.jpg'),
  summaryPath:        path.join(renderDir, 'phase3_complete.json'),
} }];

const fs   = require('fs');
const vars = $input.first().json;

fs.mkdirSync(vars.renderDir, { recursive: true });

const imagesDir = vars.projectDir + '/images';
const videosDir = vars.projectDir + '/videos';
const musicDir  = vars.projectDir + '/music';
const sfxDir    = vars.projectDir + '/sfx';

const imageCount = fs.existsSync(imagesDir) ? fs.readdirSync(imagesDir).filter(f => /\.(png|jpg)$/i.test(f)).length : 0;
const videoCount = fs.existsSync(videosDir) ? fs.readdirSync(videosDir).filter(f => f.endsWith('.mp4')).length  : 0;
const musicCount = fs.existsSync(musicDir)  ? fs.readdirSync(musicDir).filter(f => f.endsWith('.mp3')).length  : 0;
const sfxCount   = fs.existsSync(sfxDir)    ? fs.readdirSync(sfxDir).filter(f => f.endsWith('.mp3')).length    : 0;
const hasVoiceover = fs.existsSync(vars.projectDir + '/audio/voiceover_final.mp3');

if (!hasVoiceover)
  throw new Error('voiceover_final.mp3 not found. Run Phase 1 first.');

const timeline    = JSON.parse(fs.readFileSync(vars.timelinePath, 'utf-8'));
const totalScenes  = timeline.scenes.length;
// Scenes satisfied by a Wikimedia stock photo carry an explicit asset_path
// pointing into stocks/16x9 and never produce a file in images/ or videos/.
// Counting them as "expected" made this gate demand a file that by design will
// never exist, blocking the render with a false "missing assets" (Derinkuyu
// 2026-08-11: 100 generated images vs 101 image scenes, 1 of them stock).
const imageScenes  = timeline.scenes.filter(s => s.visual_type === 'image' && !s.asset_path).length;
const videoScenes  = timeline.scenes.filter(s => s.visual_type === 'video' && !s.asset_path).length;
const stockScenes  = timeline.scenes.filter(s => s.asset_path).length;
const pinnedScenes = timeline.scenes.filter(s => s.visual_type && s.visual_type.startsWith('pinned')).length;
const totalDuration = timeline.total_duration_seconds || 0;
const musicCues    = (timeline.music_cues || []).length;
const sfxCues      = (timeline.sfx_cues   || []).length;

console.log(`Asset inventory:\n  Images:    ${imageCount} / ${imageScenes} scenes\n  Videos:    ${videoCount} / ${videoScenes} scenes\n  Stock:     ${stockScenes} (wikimedia, pre-satisfied)\n  Music:     ${musicCount} / ${musicCues} cue files\n  SFX:       ${sfxCount} / ${sfxCues} cue files\n  Voiceover: YES\n  Duration:  ${(totalDuration/60).toFixed(1)} min (${totalScenes} scenes)`);

// Gate: don't launch a render until every expected asset actually exists on disk.
// Previously this node only *computed* counts and never compared them against what
// the timeline expects, so Launch Render fired even while Phase 2 was still
// generating images/video/music/sfx (a known failure mode while Phase 2's
// token-exhaustion bug is unresolved) — producing a render that exits early on
// "missing assets," which Check Render then misreported as a crash.
const missingAssets = [];
if (imageCount < imageScenes) missingAssets.push(`images (${imageCount}/${imageScenes})`);
if (videoCount < videoScenes) missingAssets.push(`videos (${videoCount}/${videoScenes})`);
if (musicCount < musicCues)   missingAssets.push(`music (${musicCount}/${musicCues})`);
if (sfxCount   < sfxCues)     missingAssets.push(`sfx (${sfxCount}/${sfxCues})`);

const assetsComplete = missingAssets.length === 0;
if (!assetsComplete) console.error(`[Phase 3] Assets not ready for "${vars.slug}" — missing: ${missingAssets.join(', ')}`);

return [{ json: { ...vars, imageCount, videoCount, musicCount, sfxCount, totalScenes, totalDuration, assetsComplete, missingAssets } }];

const fs   = require('fs');
const vars = (() => { try { return $('Load Project').first().json; } catch (_) {} return $('Load from Webhook').first().json; })();
const sd   = $getWorkflowStaticData('global');

// Scope the attempt counter per-episode. A global counter meant every execution
// after the very first one ever run would see renderCheckAttempts > 1 on its
// first poll, breaking the "skip crash-check on first poll" safeguard below and
// causing false-positive crash detection on healthy, actively-running renders.
const attemptsKey = `renderCheckAttempts__${vars.slug}`;
sd[attemptsKey] = (sd[attemptsKey] || 0) + 1;
const renderCheckAttempts = sd[attemptsKey];
const MAX_ATTEMPTS = 180;

const isComplete = fs.existsSync(vars.renderCompletePath);

// Detect a crashed render process. process.kill(pid, 0) has been observed to throw
// against a verifiably-alive PID (false ESRCH/EPERM, apparently from inside the
// task-runner sandbox) -- e.g. 2026-06-15, Easter Island episode: poll #2 reported
// crashed=true while render.js (same PID) was actively encoding scene 12/180. A
// single flaky kill() result must not be enough to flip the episode to "error".
//
// 2026-08-16, Nan Madol episode: the 90s staleness threshold below was ALSO too
// tight on its own -- process.kill() is already known-unreliable in this sandbox
// (see above), so crash detection effectively reduced to log-staleness alone. The
// final full-video crossfade encode (one ffmpeg pass re-muxing all batch segments
// with xfade transitions) legitimately went 328s+ between log writes while healthy
// and still actively encoding. Poll landed mid-gap, workflow declared the render
// crashed and wrote .status=error, while render.js kept running in the background
// and finished cleanly ~2 hours later with a fully valid final_video.mp4 (151/151
// scenes, 0 missing assets). Raised the threshold well past the observed gap.
//
// So "crashed" now requires BOTH:
//   1. process.kill(pid, 0) fails (PID file missing/unparseable, or process gone), AND
//   2. render.log has not been modified in STALE_THRESHOLD_MS -- i.e. nothing is
//      actively writing output, which is the real signal that work has stopped.
// The crash check (both halves) is skipped entirely on the first poll, same as
// before -- the process may not have forked yet and render.log may not exist.
const STALE_THRESHOLD_MS = 10 * 60 * 1000; // no log activity for 10min = likely dead

let processAlive = true;
let killCheckNote = 'skipped (first poll)';
if (renderCheckAttempts > 1) {
  try {
    const pidRaw = fs.readFileSync(vars.renderPidPath, 'utf-8').trim();
    const pid = parseInt(pidRaw, 10);
    if (isNaN(pid)) throw new Error(`unparseable pid "${pidRaw}"`);
    process.kill(pid, 0);
    killCheckNote = `pid ${pid} alive`;
  } catch (e) {
    processAlive = false;
    killCheckNote = `pid check failed: ${e.code || e.message || e}`;
  }
}

let logAgeMs = null;
let logStale = false;
try {
  logAgeMs = Date.now() - fs.statSync(vars.renderLogPath).mtimeMs;
  logStale = logAgeMs > STALE_THRESHOLD_MS;
} catch (e) {
  // render.log doesn't exist yet -- only treat as stale once we're past the first poll
  logStale = renderCheckAttempts > 1;
}

const crashed = !isComplete && !processAlive && logStale && renderCheckAttempts > 1;

let progress = '';
if (fs.existsSync(vars.renderLogPath)) {
  try {
    const logContent = fs.readFileSync(vars.renderLogPath, 'utf-8');
    const lines = logContent.trim().split('\n').filter(Boolean);
    progress = lines.slice(-2).join(' | ');
  } catch(e) {}
}

const logAgeStr = logAgeMs === null ? 'n/a' : Math.round(logAgeMs);
console.log(`Render check ${renderCheckAttempts}/${MAX_ATTEMPTS}: complete=${isComplete} ${killCheckNote} logAgeMs=${logAgeStr}`);
if (progress) console.log(`Log: ${progress}`);
if (!processAlive && !logStale) console.warn(`[Phase 3] PID check failed for "${vars.slug}" (${killCheckNote}) but render.log updated ${logAgeStr}ms ago -- treating as alive, not crashed.`);
if (crashed) console.error(`[Phase 3] Render process for "${vars.slug}" appears to have crashed -- ${killCheckNote} AND render.log stale for ${logAgeStr}ms. Last log: ${progress || '(empty)'}`);

if (!isComplete && !crashed && renderCheckAttempts >= MAX_ATTEMPTS)
  throw new Error(`Render timeout (${MAX_ATTEMPTS} checks). Check log: ${vars.renderLogPath}`);

// Clean up the per-episode counter once this render run is finished (complete or
// crashed) so workflow static data doesn't accumulate entries across episodes.
if (isComplete || crashed) delete sd[attemptsKey];

return [{ json: { ...vars, isComplete, crashed, renderAttempts: renderCheckAttempts, progress } }];

const topic = (() => { try { return $('Load Project').first().json; } catch (_) {} return $('Load from Webhook').first().json; })().topic;
const allRows = $input.all();
const matched = allRows.find(r => r.json.TOPIC === topic);
if (!matched) throw new Error(`No Ideas row found with TOPIC: ${topic}`);
return [matched];

const fs   = require('fs');
const vars = (() => { try { return $('Load Project').first().json; } catch (_) {} return $('Load from Webhook').first().json; })();
const sd   = $getWorkflowStaticData('global');

const complete = JSON.parse(fs.readFileSync(vars.renderCompletePath, 'utf-8'));

const summary = {
  project:        vars.slug,
  topic:          vars.topic,
  phase3Complete: true,
  completedAt:    new Date().toISOString(),
  render: {
    outputPath:      complete.output_path,
    durationSeconds: complete.duration_seconds,
    durationMin:     parseFloat((complete.duration_seconds / 60).toFixed(1)),
    scenesRendered:  complete.scenes_rendered,
    assetsFound:     complete.assets_found,
    assetsMissing:   complete.assets_missing,
    renderComplete:  complete.completed_at,
  },
};

fs.writeFileSync(vars.summaryPath, JSON.stringify(summary, null, 2));
sd.renderCheckAttempts = 0;

console.log('=== PHASE 3 COMPLETE ===');
console.log('Video   :', summary.render.outputPath);
console.log('Duration:', summary.render.durationMin, 'min');
console.log('Scenes  :', summary.render.scenesRendered, '(' + summary.render.assetsMissing + ' fallback black)');
console.log('Thumbnails: generate via the Web UI episode page');

return [{ json: summary }];

const input = $input.first().json;
const vars  = (() => { try { return $('Load Project').first().json; } catch (_) {} try { return $('Load from Webhook').first().json; } catch (_) {} return {}; })();
const slug  = vars.slug || input.slug || 'unknown-episode';

const stage = input.stage
  || (input.error ? 'validate_assets'
  : (input.crashed ? 'render' : 'unknown'));

const message = (input.error && input.error.message) || input.error
  || (input.crashed ? `Render process died unexpectedly without completing. Last log: ${input.progress || '(empty)'}` : 'Unknown failure');

console.error(`[Phase 3 ERROR] "${slug}" failed at stage "${stage}": ${message}`);

return [{ json: { slug, stage, error: String(message), failedAt: new Date().toISOString() } }];

const fs   = require('fs');
const path = require('path');
const slug = ($json.body && $json.body.slug) ? $json.body.slug : $json.slug;
if (!slug) throw new Error('No slug in webhook body — expected { slug: "episode_slug" }');
const projectDir = '/Users/jneal/n8n_projects/' + slug;
if (!fs.existsSync(projectDir)) throw new Error('Project not found: ' + projectDir);
const timelinePath = path.join(projectDir, 'scripts', 'media_timeline.json');
const timeline     = JSON.parse(fs.readFileSync(timelinePath, 'utf-8'));
const topic        = timeline.topic || slug;
const renderDir    = path.join(projectDir, 'renders');

// Write execution -> projectDir mapping for error trigger
const execMapDir = '/Users/jneal/n8n_projects/.exec_map';
fs.mkdirSync(execMapDir, { recursive: true });
fs.writeFileSync(path.join(execMapDir, $execution.id), projectDir, 'utf-8');

return [{ json: {
  slug, projectDir, topic, timelinePath, renderDir,
  renderScript:       '/Users/jneal/n8n_projects/render.js',
  renderLogPath:      path.join(renderDir, 'render.log'),
  renderPidPath:      path.join(renderDir, 'render.pid'),
  renderCompletePath: path.join(renderDir, 'render_complete.json'),
  finalVideoPath:     path.join(renderDir, 'final_video.mp4'),
  thumbnailPath:      path.join(renderDir, 'thumbnail.jpg'),
  summaryPath:        path.join(renderDir, 'phase3_complete.json'),
} }];

const execId = $json.execution.id;
const fs   = require('fs');
const path = require('path');
const mapFile = '/Users/jneal/n8n_projects/.exec_map/' + execId;

let projectDir;
try {
  projectDir = fs.readFileSync(mapFile, 'utf-8').trim();
} catch {
  console.log('[ERROR TRIGGER] No exec mapping for', execId);
  return [{ json: { handled: false, execId } }];
}

const errMsg = ($json.execution && $json.execution.error && $json.execution.error.message) || '';
const pauseMatch = errMsg.match(/^USAGE_LIMIT_PAUSE\|(.*)$/);

try {
  if (pauseMatch) {
    const retryAfter = pauseMatch[1] || null;
    fs.writeFileSync(path.join(projectDir, '.status'), 'paused_until', 'utf-8');
    fs.writeFileSync(path.join(projectDir, '.paused_until'), JSON.stringify({
      retryAfter,
      phase: 3,
      pausedAt: new Date().toISOString()
    }, null, 2), 'utf-8');
    console.log('[ERROR TRIGGER] Usage limit reached — paused', projectDir, 'until', retryAfter);
  } else {
    fs.writeFileSync(path.join(projectDir, '.status'), 'error', 'utf-8');
    console.log('[ERROR TRIGGER] Wrote error status to', projectDir);
  }
} catch (e) {
  console.log('[ERROR TRIGGER] Failed to write status:', e.message);
}

try { fs.unlinkSync(mapFile); } catch {}

return [{ json: { handled: true, projectDir, execId, paused: !!pauseMatch } }];

const vars = $input.first().json;
const missing = vars.missingAssets || [];

console.error(`[Phase 3] Stopped before launching render for "${vars.slug}" — missing assets: ${missing.join(', ')}. This usually means Phase 2 hasn't finished yet (known token-exhaustion issue requires a manual nudge). Re-run Phase 3 for this episode once Phase 2 completes.`);

return [{ json: { ...vars, phase3Status: 'assets_not_ready', missingAssets: missing } }];
